cat > test_all_examples.sh << 'EOF'
#!/bin/bash
set -e

echo "=== Example 1: Basic call with parameters ==="
cat > ex1.json << 'JSON'
{
  "defs": {
    "Normalize": { "steps":[
      {"op":"map","as":"z","expr":"(value - params.mean) / params.std"}
    ]},
    "KeepCols": { "steps":[
      {"op":"select","columns":["id","z"]}
    ]}
  },
  "pipeline": {
    "steps": [
      {"op":"call","name":"Normalize","params":{"mean":100,"std":20}},
      {"op":"call","name":"KeepCols","params":{}}
    ]
  },
  "dataset":[
    {"id":1,"value":120},
    {"id":2,"value":80}
  ]
}
JSON
result=$(python etl_pipeline.py --execute < ex1.json)
expected='{"status":"ok","data":[{"id":1,"z":1},{"id":2,"z":-1}],"metrics":{"rows_in":2,"rows_out":2}}'
if [ "$result" = "$expected" ]; then
  echo "✓ PASS"
else
  echo "✗ FAIL"
  echo "Expected: $expected"
  echo "Got: $result"
fi

echo ""
echo "=== Example 2: Missing definition ==="
cat > ex2.json << 'JSON'
{
  "defs": {},
  "pipeline": { "steps": [ {"op":"call","name":"Missing","params":{}} ] },
  "dataset":[{"id":1}]
}
JSON
result=$(python etl_pipeline.py --execute < ex2.json 2>&1)
if echo "$result" | grep -q '"error_code":"UNKNOWN_DEF"' && echo "$result" | grep -q '"path":"pipeline.steps\[0\].name"'; then
  echo "✓ PASS"
else
  echo "✗ FAIL"
  echo "Got: $result"
fi

echo ""
echo "=== Example 3: Direct recursion ==="
cat > ex3.json << 'JSON'
{
  "defs": {
    "Loop": { "steps":[ {"op":"call","name":"Loop","params":{}} ] }
  },
  "pipeline": { "steps": [ {"op":"call","name":"Loop","params":{}} ] },
  "dataset":[{"id":1}]
}
JSON
result=$(python etl_pipeline.py --execute < ex3.json 2>&1)
if echo "$result" | grep -q '"error_code":"RECURSION_FORBIDDEN"' && echo "$result" | grep -q '"path":"defs\[Loop\].steps\[0\].name"'; then
  echo "✓ PASS"
else
  echo "✗ FAIL"
  echo "Got: $result"
fi
EOF
chmod +x test_all_examples.sh
./test_all_examples.sh

